<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function attendance_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())attendance_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))attendance_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$role=(string)$_SESSION['role'];$roles=['admin','director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher'];if(!in_array($role,$roles,true))attendance_json(403,['ok'=>false,'message'=>'Your role cannot access attendance reports.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$start=(string)($_GET['start_date']??'');$end=(string)($_GET['end_date']??'');$class=trim((string)($_GET['class_level']??''));$validDate=static fn(string $d):bool=>(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)&&checkdate((int)substr($d,5,2),(int)substr($d,8,2),(int)substr($d,0,4));if(!$school||!$validDate($start)||!$validDate($end)||$start>$end||((strtotime($end)-strtotime($start))/86400)>365)attendance_json(422,['ok'=>false,'message'=>'Choose a valid date range of no more than 366 days.']);
$db=db();try{$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())attendance_json(403,['ok'=>false,'message'=>'That school is outside your access.']);if($class!==''){$q=$db->prepare('SELECT 1 FROM school_classes WHERE school_id=? AND name=?');$q->execute([$school,$class]);if(!$q->fetchColumn())attendance_json(404,['ok'=>false,'message'=>'Class not found in this school.']);if($role==='teacher'){$q=$db->prepare('SELECT 1 FROM teacher_assignments WHERE user_id=? AND school_id=? AND class_level=? AND active=1 LIMIT 1');$q->execute([$uid,$school,$class]);if(!$q->fetchColumn())attendance_json(403,['ok'=>false,'message'=>'Attendance reporting is limited to your assigned classes.']);}}
$scope='';$params=[$school,$start,$end];if($class!==''){$scope.=' AND p.class_level=?';$params[]=$class;}if($role==='teacher'){$scope.=' AND EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=p.school_id AND a.class_level=p.class_level AND a.active=1)';$params[]=$uid;}
$q=$db->prepare("SELECT p.class_level,a.attendance_status,COUNT(*) total FROM pupil_attendance a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id WHERE a.school_id=? AND a.attendance_date BETWEEN ? AND ?$scope GROUP BY p.class_level,a.attendance_status ORDER BY p.class_level,a.attendance_status");$q->execute($params);$byClass=$q->fetchAll();$q=$db->prepare("SELECT a.attendance_date,COUNT(*) marked,SUM(a.attendance_status='present') present,SUM(a.attendance_status='absent') absent,SUM(a.attendance_status='late') late,SUM(a.attendance_status='excused') excused FROM pupil_attendance a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id WHERE a.school_id=? AND a.attendance_date BETWEEN ? AND ?$scope GROUP BY a.attendance_date ORDER BY a.attendance_date");$q->execute($params);attendance_json(200,['ok'=>true,'data'=>['by_class'=>$byClass,'by_date'=>$q->fetchAll(),'start_date'=>$start,'end_date'=>$end]]);}catch(Throwable $e){error_log('Attendance report error: '.$e->getMessage());attendance_json(500,['ok'=>false,'message'=>'Attendance summary could not be loaded.']);}
